<?php

namespace App\Exports;

use App\Models\ReportRun;
use Maatwebsite\Excel\Concerns\FromArray;

class ReportRunsExport implements FromArray
{
    public function array(): array
    {
        $rows = [[
            'Report',
            'Format',
            'Status',
            'File',
            'Rows',
            'Generated By',
            'Generated At',
            'Failure',
        ]];

        $runs =
            ReportRun::query()
                ->with('generator')
                ->latest(
                    'generated_at'
                )
                ->get();

        foreach (
            $runs as $run
        ) {
            $rows[] = [
                $run->report_type,

                $run->format,

                $run->status,

                $run->download_name,

                $run->row_count,

                $run
                    ->generator
                    ?->name,

                $run
                    ->generated_at
                    ->format(
                        'Y-m-d H:i:s'
                    ),

                $run
                    ->failure_message,
            ];
        }

        return $rows;
    }
}
